pub struct Order {                  // private fields: no other module may build or mutate it
    id: OrderId, lines: Vec<OrderLine>, total: i64, limit: i64,
}
impl Order {                         // Order::new(...) validates and is the only constructor
    pub fn add_line(&mut self, line: OrderLine) -> Result<(), DomainError> {
        if self.total + line.amount() > self.limit { return Err(DomainError::CreditLimit); }
        self.total += line.amount();
        self.lines.push(line);          // invariant re-established
        Ok(())
    }
    pub fn lines(&self) -> &[OrderLine] { &self.lines }   // read-only borrow, no clone
}
